        if lines[i]:
            l, r = map(int, lines[i].split())
            offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        st = SegmentTree(n + 2)
        total = 0

        for l, r in offers:
            duration = r - l + 1

            if duration >= x:
                if st.query(1, 1, n + 1, l, r):
