def solution(input_str):
    import os
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    # Read costs: A[i][j] = cost for city i to build rail to city j
    # Note: A_{i,i} is skipped in each line
    costs = [[0] * N for _ in range(N)]
    for i in range(N):
        parts = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(N):
            if j == i:
                continue
            costs[i][j] = parts[idx]
            idx += 1

    # Build preference list for each city
    # Lower cost = higher preference
    preference = [[0] * N for _ in range(N)]
    for i in range(N):
        costs_to_others = []
        for j in range(N):
            if i != j:
                costs_to_others.append((costs[i][j], j))
        costs_to_others.sort()
        for rank, (_, j) in enumerate(costs_to_others):
            preference[i][j] = rank

    # Gale-Shapley algorithm
    # Each free city proposes to their highest preferred non-rejected city

    next_proposal_idx = [0] * N  # Which preference in list to propose next
    partner = [-1] * N           # partner[i] = who i is paired with

    free = list(range(N))

    while free:
        i = free.pop(0)
        found = False

        while next_proposal_idx[i] < N:
            j = preference[i][__builtins__['range'](N)][next_proposal_idx[i]]

            # Check if j is already within valid range (0 to N-1)
            if j < 0 or j >= N:
                next_proposal_idx[i] += 1
                continue

            if partner[j] == -1:
                # j is free, accept
                partner[j] = i
                partner[i] = j
                found = True
                break
            else:
                current = partner[j]
                # j compares i and current
                if preference[j][i] < preference[j][current]:
                    # j prefers i, break with i
                    partner[j] = i
                    partner[current] = -1
                    # current becomes free
                    next_proposal_idx[current] += 1
                    partner[i] = j
                    found = True
                    break
                else:
                    # j prefers current, reject i
                    next_proposal_idx[i] += 1

        if not found:
            # No available city i can match with
            continue

    # Build and verify the matching
    # cities are paired if partner[i] == j and partner[j] == i

    result = [0] * N
    for i in range(N):
        result[i] = partner[i] + 1 if partner[i] != -1 else -1

    # Return result as string
    return '\n'.join(map(str, result)) + '\n'

