                    ratios.append(1.0)  # 0/0 undefined, but if both same, ratio=1 is fine
                else:
                    ratios.append(0.0)  # non-zero / 0 -> undefined but effectively 0 ratio from here
            else:
                ratios.append(seq[i] / seq[i-1])

        # Check all ratios are same (with tolerance for float)
        if not ratios:
