            if not divisors:
                results.append("0\n0\n")
                continue

            # Prime factorization
            prime_factors = set()
            temp = n
            d = 2
            while d * d <= temp:
                while temp % d == 0:
                    prime_factors.add(d)
                    temp //= d
                d += 1
            if temp > 1:
                prime_factors.add(temp)

            # Group divisors by prime factors for better arrangement
            # Divisors can be arranged to share prime factors with neighbors

            if len(prime_factors) == 1:
                # All divisors share at least one common prime factor
                # Any arrangement works with 0 moves
                sorted_divs = sorted(divisors)
                results.append(f"{' '.join(map(str, sorted_divs))}\n0\n")
            else:
                # Try to find arrangement with 0 moves
                # Common strategy: place divisors in order based on prime factors

                if len(divisors) <= 8:
                    # Try permutations for small number of divisors
                    import itertools
                    best_moves = float('inf')
                    best_perm = None

                    for perm in itertools.permutations(divisors):
