                    # Group divisors that share common prime factors
                    result = []
                    remaining = divisors[:]

                    for p in sorted(prime_factors):
                        # Find divisors containing this prime
                        for i in range(len(remaining)):
                            if remaining[i] % p == 0:
                                result.append(remaining[i])
                                remaining[i] = None
                                break

