    # Check which wave this position is in

    def solve_brute(n):
        """Brute force simulation for small n"""
        from collections import defaultdict
        grid = defaultdict(int)
        grid[(0,0)] = n

        changed = True
        while changed:
            changed = False
            # Work on copies to allow multiple updates
            new_grid = defaultdict(int)
            for (x,y), cnt in grid.items():
                new_grid[(x,y)] = cnt

            # Process each position
            list_to_remove = []
            for (x,y), cnt in new_grid.items():
                if cnt >= 4:
                    new_grid[(x,y)] = cnt - 4
                    for nx, ny in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
                        new_grid[(nx,ny)] += 1
                    list_to_remove.append((x,y))

            # Apply all spreads
            for pos in list_to_remove:
                grid[(pos[0], pos[1])] -= 4
                for nx, ny in [(pos[0]+1,pos[1]),(pos[0]-1,pos[1]),(pos[0],pos[1]+1),(pos[0],pos[1]-1)]:
                    grid[(nx,ny)] += 1

            if any(cnt > 4 for cnt in grid.values()):
                changed = True
                continue
            # Break when all have < 4
            for pos in list(grid.keys()):
                if grid[pos] >= 4:
                    return None
            return dict(grid)

    # Actually use a smarter approach
    # The pattern is: at each distance d, ants distribute in (2d+1) positions at that level

    result_map = {}

    # Key realization: simulate only necessary steps
    # With n ants, we can compute max distance reached

