def solve_game(n, u, r, a, b, k, p):
    """Solve the max points game problem"""
    max_score = float('-inf')

    def get_score(arr):
        return sum(arr[i] * k[i] for i in range(n))

    def dfs(step, current_a):
        nonlocal max_score
        if step == u:
            max_score = max(max_score, get_score(current_a))
            return

        # Type 1 operation: XOR with b
        new_a = [current_a[i] ^ b[i] for i in range(n)]
        dfs(step + 1, new_a)

        # Type 2 operation: permute by p and add r
        new_a = [current_a[p[i]] + r for i in range(n)]
        dfs(step + 1, new_a)

    dfs(0, list(a))
    return max_score

