from math import gcd

def solution(s):
    n, l, r = map(int, s.split())

    if n == 1:
        return str(r - l + 1)

    if n == 2:
        # Any pair of distinct numbers [l,r] works
        # Count = (r - l + 1) choices for first * (r - l) choices for second
        return str((r - l + 1) * (r - l))

    # For n >= 3, we need to find geometric progressions
    # A GP with ratio p/q (in lowest terms, p != q) has terms:
    # k*q^{n-1}, k*p*q^{n-2}, ..., k*p^{n-1}
    # All must be in [l, r]

    res = 0

    # p^{n-1} <= r and q^{n-1} <= r are necessary conditions
    max_val = int(r ** (1.0 / (n - 1))) if n > 1 else r + 1

    for p in range(1, max_val + 1):
        for q in range(1, max_val + 1):
            if gcd(p, q) != 1:
                continue
            if p == q:
                # All terms equal, but need distinct terms for n >= 2
                continue

            pp = p ** (n - 1)
            qq = q ** (n - 1)

            # If either power exceeds r, this ratio is invalid
            if pp > r or qq > r:
                continue

            if p > q:
                # Increasing progression
                # l <= k*qq and k*pp <= r
                min_k = (l + qq - 1) // qq
                max_k = r // pp
            else:
                # Decreasing progression
                # l <= k*pp and k*qq <= r
                min_k = (l + pp - 1) // pp
                max_k = r // qq

            if max_k >= min_k:
                res += max_k - min_k + 1

    return str(res)

Looking at this problem, I need to count valid love/hate relationship configurations for n vertices where every triangle must have either exactly 1 or 3 love pairs.

The key insight is that valid configurations correspond to assigning each vertex to one of two "groups" (like a 2-coloring), where:
- Two vertices love each other iff they're in the SAME group
- Two vertices hate each other iff they're in DIFFERENT groups

This creates a valid structure where triangles can have:
- 3 love edges (all 3 vertices same group) ✓
- 1 love edge (2 same group, 1 different) ✓
- Invalid cases are prevented by the structure

