        edges.append((u, v))

    # Adjacency list for the given tree structure
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Calculate degree product sum (term 1)
    term1 = sum(len(adj[u]) * a[u - 1] for u in range(1, n + 1))

    # Calculate edge contributions (term 2)
    term2 = 0

    # For each node, calculate distances to all other nodes
    min_weight_node = a.index(min(a)) + 1  # 1-indexed

    for start in range(1, n + 1):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)

        # For each node, consider edges
        for u in range(1, n + 1):
            if dist[u] == -1:
                continue
            for v in adj[u]:
                d = dist[u] if u == start else dist[v]
                # If u and v are adjacent, dist = 1
                d = 1

                if d >= 1:
                    term2 += int(ceil(log2(d))) * min(a[u - 1], a[v - 1])

    result = term1 + term2
    return str(result)


