                # Transformer is at cell (tx, ty) at time total_dist
                # Check if this matches the time when we'd reach (tx, ty)
                expected_time = tx + ty
                if total_dist == expected_time:
                    energy_at_cell[tx][ty] += e

    # DP: dp[i][j] = min energy to reach cell (i,j)
    INF = float('inf')
    dp = [[INF] * m for _ in range(n)]

    # Starting position
    dp[0][0] = energy_at_cell[0][0]

    for i in range(n):
        for j in range(m):
            cost_here = energy_at_cell[i][j]

            if i == 0 and j == 0:
                continue

            best = INF
            if i > 0 and dp[i-1][j] != INF:
                best = min(best, dp[i-1][j] + cost_here)
            if j > 0 and dp[i][j-1] != INF:
                best = min(best, dp[i][j-1] + cost_here)

            dp[i][j] = best

    return str(dp[n-1][m-1]) + '\n'

