import sys

MOD = 10**9 + 7

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.components = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx != ry:
            self.parent[rx] = ry
            self.components -= 1
            return True
        return False

def single_constraint(n, l, k):
    """Compute probability when X_l = 1 using union-find"""
    uf = UnionFind(n)
    for a in range(l):
        uf.union(a, n - l + a)
    return pow(k, uf.components, MOD)

def pair_constraint(n, i, j, k):
    """Compute probability when both X_i=1 and X_j=1 (i < j)"""
    uf = UnionFind(n)

    # Apply X_j constraints
    for a in range(j):
        uf.union(a, n - j + a)

    # Apply X_i constraints
    for a in range(i):
        uf.union(a, n - i + a)

    return pow(k, uf.components, MOD)

def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return "0"

    parts = input_str.split()
    n = int(parts[0])
    k = int(parts[1])

    if n == 1:
        os._exit(0)
        return "0"

    if k == 1:
        result = (n - 1) ** 2
        return str(result % MOD)

    result = 0

    # Single terms: sum of E[X_i] for i in 1 to n-1
    for i in range(1, n):
        prob = single_constraint(n, i, k)
        result = (result + prob) % MOD

    # Pair terms: 2 * sum of E[X_i * X_j] for 1 <= i < j <= n-1
    for i in range(1, n):
        for j in range(i + 1, n):
            prob = pair_constraint(n, i, j, k)
            result = (result + prob) % MOD

    result = (result * 2) % MOD

    return str(result % MOD)

