        path_v = get_path_to_root(v, None)

        lca = path_u[-1] if not path_v else None
        for i in range(len(path_u) - 1, -1, -1):
            if path_u[i] in path_v:
                lca = path_u[i]
                break

        if lca is None:
            return [u, v]

        path_u = [node for node in path_u if node >= lca]
        path_v = [node for node in path_v if node >= lca]

        return path_u + path_v[::-1][1:]

    def get_path_vertices(self, u, v):
        """Get all vertices on simple path from u to v"""
        path = self.get_lca_path(u, v)
        return set(path)

