def sqfree(x):
    res = 1
    d = 2
    while d * d <= x:
        cnt = 0
        while x % d == 0:
            cnt += 1
            x //= d
        if cnt & 1:
            res *= d
        d += 1
    if x > 1:
        res *= x
    return res

